export default function OperationTipsPage() {
  const { theme } = useOutletContext<{ theme: ThemeConfig; festival: FestivalBadge }>();
  const [activePlatformTab, setActivePlatformTab] = useState('all');
  const [activeCategory, setActiveCategory] = useState<IOperationTip['category'] | 'all'>('all');
  const [keyword, setKeyword] = useState('');
  const today = useMemo(() => new Date(), []);

  // ===== 折叠面板手风琴状态 =====
  const [expandedId, setExpandedId] = useState<string>('header');
  function toggleSection(id: string) {
    setExpandedId((prev) => (prev === id ? '' : id));
  }

  const [operationNotes, setOperationNotes] = useState<NoteItem[]>([]);

  // 技巧卡片展开状态（仅手机端折叠时用）
  const [expandedTipId, setExpandedTipId] = useState<string | null>(null);

  function toggleTip(id: string) {
    setExpandedTipId(prev => prev === id ? null : id);
  }

  // 技巧数据：从 JSON 动态加载，减少初始 JS chunk 体积
  const [tipsGroups, setTipsGroups] = useState<IOperationTip[][]>([]);
  const [dataLoading, setDataLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    import('@/data/json/operation-tips.json')
      .then((mod) => {
        if (cancelled) return;
        setTipsGroups(mod.default as IOperationTip[][]);
        setDataLoading(false);
      })
      .catch(() => {
        if (cancelled) return;
        setTipsGroups([]);
        setDataLoading(false);
      });
    return () => { cancelled = true; };
  }, []);

  // 全部技巧（合并所有组，供搜索使用）
  const allTips = useMemo(() => tipsGroups.flat(), [tipsGroups]);

  // 当日推荐：7个分类各保底至少1条 + 额外1~4条随机分配 + 分类内按天轮转
  // 每天总数 8~11 条浮动，任何分类都不为0
  const dailyTips = useMemo(() => {
    const categoryOrder: IOperationTip['category'][] = ['运营', '出单', '广告', '风控', '投流', '售后', '社媒外贸'];
    // 按分类分组
    const byCategory = new Map<string, IOperationTip[]>();
    for (const tip of allTips) {
      if (!byCategory.has(tip.category)) byCategory.set(tip.category, []);
      byCategory.get(tip.category)!.push(tip);
    }
    // 有效日期（8点前显示前一天的）
    const d = new Date(today);
    if (d.getHours() < 8) d.setDate(d.getDate() - 1);
    const dayOfYear = Math.floor((d.getTime() - new Date(d.getFullYear(), 0, 0).getTime()) / 86400000);

    // 保底1：每个分类各取1条，分类内按天轮转偏移
    const result: IOperationTip[] = [];
    // 记录每个分类已用了哪些索引（避免重复）
    const usedIndices: Record<string, number[]> = {};

    categoryOrder.forEach((cat, ci) => {
      const catTips = byCategory.get(cat);
      if (!catTips || catTips.length === 0) return;
      // 每个分类用不同的偏移基数（分类索引*13），保证不同分类轮转错位
      const idx = (dayOfYear + ci * 13) % catTips.length;
      result.push(catTips[idx]);
      usedIndices[cat] = [idx];
    });

    // 种子随机数发生器（同一天结果稳定，跨天变化）
    let seed = (dayOfYear * 1103515245 + 12345) & 0x7fffffff;
    const rand = () => {
      seed = (seed * 1103515245 + 12345) & 0x7fffffff;
      return seed / 0x7fffffff;
    };

    // 额外 1~4 条，随机分配到各分类
    const extraCount = 1 + (dayOfYear % 4); // 结果 1,2,3,4
    for (let i = 0; i < extraCount; i++) {
      // 候选分类：该分类还有未取过的条目
      const candidates = categoryOrder.filter(cat => {
        const catTips = byCategory.get(cat);
        if (!catTips) return false;
        const used = usedIndices[cat]?.length || 0;
        return used < catTips.length;
      });
      if (candidates.length === 0) break;

      // 随机选一个分类
      const cat = candidates[Math.floor(rand() * candidates.length)];
      const catTips = byCategory.get(cat)!;
      const usedIdx = usedIndices[cat];

      // 从该分类取下一个未用的条目（继续按天轮转方向找）
      let nextIdx = -1;
      for (let j = 1; j <= catTips.length; j++) {
        const candidateIdx = ((dayOfYear + categoryOrder.indexOf(cat) * 13) + j) % catTips.length;
        if (!usedIdx.includes(candidateIdx)) {
          nextIdx = candidateIdx;
          break;
        }
      }
      if (nextIdx === -1) continue;

      result.push(catTips[nextIdx]);
      usedIdx.push(nextIdx);
    }

    // 按天打散顺序，保证同一天分类顺序不是固定的「运营→出单→...」
    const shuffled = [...result];
    let s = dayOfYear * 2654435761;
    const rand2 = () => {
      s = (s * 1664525 + 1013904223) & 0xffffffff;
      return (s >>> 0) / 0xffffffff;
    };
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(rand2() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }

    return shuffled;
  }, [today, allTips]);

  // 搜索结果：严格相关——单关键词必须在标题/分类/平台/子组/同义词命中，或正文出现≥2次；杜绝正文顺带一提就被召回
  const searchResults = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    if (!kw) return null;
    // 原始关键词拆分（支持空格/逗号分隔的多关键词AND）
    const rawWords = keyword.trim().split(/[\s,，]+/).filter(w => w.length >= 2);

    const scored = allTips.map(tip => {
      let score = 0;
      let strongHit = false; // 是否命中强字段（标题/分类/平台/子组/同义词）

      const titleLower = tip.title.toLowerCase();
      const descLower = tip.description.toLowerCase();
      const catLower = tip.category.toLowerCase();
      const platLower = tip.platform.toLowerCase();
      const subgLower = ((tip as any).subgroup as string || '').toLowerCase();
      const synsLower = (tip as any).synonyms as string[] || [];
      const synsList = Array.isArray(synsLower) ? synsLower.map(s => String(s).toLowerCase()) : [];

      // === 强字段命中（标题/分类/平台/子组/同义词）权重高 ===
      // 标题命中
      if (titleLower.includes(kw)) { score += 100; strongHit = true; }
      // 同义词精确匹配
      if (synsList.some(s => s === kw)) { score += 90; strongHit = true; }
      // 子组精确匹配
      if (subgLower === kw) { score += 70; strongHit = true; }
      else if (subgLower.includes(kw) && kw.length >= 2) { score += 35; if (subgLower) strongHit = true; }
      // 分类精确匹配
      if (catLower === kw || kw.includes(catLower)) { score += 50; strongHit = true; }
      // 平台精确匹配
      if (platLower.includes(kw) || kw.includes(platLower)) { score += 40; strongHit = true; }

      // === 正文命中：计算出现次数，≥2次才算有效 ===
      let descHitCount = 0;
      if (kw.length >= 2) {
        let idx = 0;
        while ((idx = descLower.indexOf(kw, idx)) !== -1) {
          descHitCount++;
          idx += kw.length;
          if (descHitCount >= 5) break; // 封顶防作弊
        }
      }
      if (descHitCount >= 2) {
        score += descHitCount * 15;
        if (descHitCount >= 3) strongHit = true; // 正文出现3次以上也算强相关
      }

      // === 多关键词 AND 验证 ===
      if (rawWords.length > 1) {
        let allStrong = true;
        let anyStrongHit = false;
        for (const w of rawWords) {
          const wl = w.toLowerCase();
          const inStrong =
            titleLower.includes(wl) ||
            catLower.includes(wl) ||
            platLower.includes(wl) ||
            subgLower.includes(wl) ||
            synsList.some(s => s.includes(wl));
          const inDesc = descLower.includes(wl);
          if (!inStrong && !inDesc) { allStrong = false; break; }
          if (inStrong) anyStrongHit = true;
          if (inStrong) score += 10;
        }
        if (!allStrong || !anyStrongHit) {
          // 多关键词必须每个都出现、且至少一个在强字段，否则不展示
          score = 0;
        }
      } else if (!strongHit) {
        // 单关键词必须命中强字段或正文≥2次（上面已处理），否则分数清零
        score = 0;
      }

      return { item: { type: 'tip' as const, data: tip }, score };
    }).filter(item => item.score > 0);

    // 我的笔记也参与搜索（内容+标签+来源）
    const noteScored = operationNotes
      .map(note => {
        let score = 0;
        const contentLower = note.content.toLowerCase();
        const tagLower = (note.tags || []).join(' ').toLowerCase();
        if (contentLower.includes(kw)) score += 80;
        if (tagLower.includes(kw)) score += 60;
        if (note.source.toLowerCase().includes(kw)) score += 40;
        return { item: { type: 'note' as const, data: note }, score };
      })
      .filter(x => x.score > 0);

    const allScored = [...scored, ...noteScored];
    allScored.sort((a, b) => b.score - a.score);
    return allScored.map(s => s.item);
  }, [keyword, allTips, operationNotes]);

  const displayTips: IOperationTip[] = !keyword.trim() ? dailyTips : [];
  const isSearchMode = keyword.trim().length > 0;

  const OP_CATEGORIES: Array<IOperationTip['category']> = ['运营', '出单', '广告', '风控', '投流', '售后', '社媒外贸', '选品'];

  const filtered = activePlatformTab === 'all' && activeCategory === 'all'
    ? displayTips
    : displayTips.filter(t =>
        (activePlatformTab === 'all' || t.platform === activePlatformTab) &&
        (activeCategory === 'all' || t.category === activeCategory)
      );

  const displayItems = useMemo(() => {
    if (!isSearchMode) return filtered.map(t => ({ type: 'tip' as const, data: t }));
    const results = searchResults as { type: 'tip' | 'note'; data: any }[] | null;
    if (!results) return [];
    return results.filter(r =>
      r.type === 'note' ||
      (r.type === 'tip' &&
        (activePlatformTab === 'all' || r.data.platform === activePlatformTab) &&
        (activeCategory === 'all' || r.data.category === activeCategory)
      )
    );
  }, [isSearchMode, searchResults, filtered, activePlatformTab, activeCategory]);

  // 数据加载中显示骨架屏
  if (dataLoading) {
    return (
      <div className="space-y-3">
        <div className="rounded-xl border border-border/60 bg-card p-5 shadow-sm">
          <div className="h-6 w-32 bg-muted/70 rounded animate-pulse mb-2" />
          <div className="h-4 w-48 bg-muted/50 rounded animate-pulse" />
        </div>
        {[0, 1, 2, 3, 4].map((i) => (
          <div key={i} className="rounded-xl border border-border/60 bg-card p-4 shadow-sm animate-pulse">
            <div className="h-5 w-3/4 bg-muted/60 rounded mb-2" />
            <div className="h-4 w-full bg-muted/40 rounded mb-2" />
            <div className="h-4 w-2/3 bg-muted/40 rounded" />
          </div>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {/* Header */}
      <CollapsibleSection
        title="运营技巧"
        subtitle="OPERATION TIPS"
        summary="每日更新跨境运营实战技巧"
        badge="每日更新"
        badgeColor="info"
        theme={theme}
        expanded={expandedId === 'header'}
        onToggle={() => toggleSection('header')}
        icon={<Lightbulb className="size-5" />}
        className="!shadow-md"
      >
        <div
          className="p-5 text-white rounded-xl"
          style={{
            background: `linear-gradient(135deg, ${theme.primary}, ${theme.primaryLight})`,
          }}
        >
          <div className="flex items-start gap-3">
            <div className="size-10 rounded-xl bg-white/15 backdrop-blur flex items-center justify-center shrink-0">
              <Lightbulb className="size-5" />
            </div>
            <div className="space-y-1">
              <div className="page-title-kicker opacity-80">OPERATION TIPS</div>
              <h1 className="page-title-main">运营技巧</h1>
              <p className="page-title-sub flex items-center gap-1">
                <Calendar className="size-3" />
                {getUpdateLabel(today)}
              </p>
            </div>
          </div>
        </div>
      </CollapsibleSection>

      {/* Category Tabs + 搜索 */}
      <CollapsibleSection
        title="技巧库"
        subtitle="搜索 · 分类 · 每日推荐"
        summary={`共 ${displayTips.length} 条技巧 · ${activePlatformTab === 'all' ? '全平台' : activePlatformTab}`}
        badge={`${displayTips.length} 条`}
        badgeColor="success"
        theme={theme}
        expanded={expandedId === 'tips'}
        onToggle={() => toggleSection('tips')}
        icon={<BookOpen className="size-5" />}
        className="!shadow-none !border-0"
      >
      <div className="space-y-3">
        {/* 搜索框 */}
        <div className="relative">
          <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            type="search"
            value={keyword}
            onChange={(e) => setKeyword(e.target.value)}
            placeholder="搜索全部运营技巧（标题/分类/平台/内容）"
            className="pl-9 pr-9 h-10 bg-background/60"
            style={{ borderColor: theme.ui.cardBorder }}
          />
          {keyword && (
            <button
              onClick={() => setKeyword('')}
              className="absolute right-2 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground p-1 rounded-md hover:bg-muted"
              aria-label="清除搜索"
            >
              <X className="size-4" />
            </button>
          )}
        </div>

        {isSearchMode && (
          <div className="flex items-center justify-between px-1">
            <span className="text-xs text-muted-foreground">
               搜索结果：找到 <span className="font-medium" style={{ color: theme.primary }}>{displayItems.length}</span> 条 / 共 {allTips.length} 条
            </span>
            <button
              onClick={() => setKeyword('')}
              className="text-xs" style={{ color: theme.primary }}
            >
              清除搜索
            </button>
          </div>
        )}
        {!isSearchMode && (
          <div className="flex items-center justify-between px-1">
            <span className="text-xs text-muted-foreground">
              <Calendar className="size-3 inline mr-1" />
              今日推荐 {dailyTips.length} 条 · 共 {allTips.length} 条干货
            </span>
          </div>
        )}

        {/* 分类筛选Chip */}
        <div className="flex items-center gap-2 overflow-x-auto pb-1 flex-nowrap">
          <button
            onClick={() => setActiveCategory('all')}
            className={`text-xs px-3 py-1 rounded-full border shrink-0 transition-colors ${
              activeCategory === 'all'
                ? 'bg-primary text-primary-foreground border-primary'
                : 'bg-background text-muted-foreground border-border hover:text-foreground'
            }`}
          >
            全部分类
          </button>
           {OP_CATEGORIES.map(cat => {
             // 非搜索模式下显示「当天该分类实际条数」，搜索模式下显示全库总数
             const count = isSearchMode
               ? allTips.filter(t => t.category === cat).length
               : dailyTips.filter(t => t.category === cat).length;
             return (
               <button
                 key={cat}
                 onClick={() => setActiveCategory(cat)}
                 className={`text-xs px-3 py-1 rounded-full border shrink-0 transition-colors ${
                   activeCategory === cat
                     ? 'bg-primary text-primary-foreground border-primary'
                     : `${categoryColors[cat]} border-transparent hover:opacity-80`
                 }`}
               >
                 {cat}
                 <span className={`ml-1 text-[10px] ${activeCategory === cat ? 'opacity-80' : 'opacity-60'}`}>
                   {count}
                 </span>
               </button>
             );
           })}
        </div>

        <div className="mt-4 space-y-3">
          {displayItems.length === 0 ? (
            <div className="text-center py-12 text-sm text-muted-foreground">
              <Search className="size-8 mx-auto mb-2 opacity-30" />
              没有找到匹配的技巧，换个关键词试试吧
            </div>
          ) : (
            displayItems.map((item) => (
              item.type === 'note' ? (
                <Card
                  key={item.data.id}
                  className="border shadow-sm hover:shadow-md transition-all overflow-hidden"
                  style={{
                    borderColor: theme.ui.cardBorder,
                    backgroundColor: theme.ui.glassBg,
                    backdropFilter: 'blur(10px) saturate(180%)',
                    WebkitBackdropFilter: 'blur(10px) saturate(180%)',
                    boxShadow: theme.ui.glassShadow,
                  }}
                >
                  <CardHeader className="pb-2">
                    <div className="flex items-start justify-between gap-2 mb-2">
                      <CardTitle className="text-base font-semibold leading-snug" style={{ color: theme.primary }}>
                        📝 我的笔记
                      </CardTitle>
                      <Badge
                        className="text-xs border-0"
                        style={{ backgroundColor: `${theme.primary}15`, color: theme.primary }}
                      >
                        {item.data.date}
                      </Badge>
                    </div>
                    <div className="flex items-center gap-2 flex-wrap">
                      <Badge className="text-xs bg-purple-100 text-purple-700 border-0">
                        我的笔记
                      </Badge>
                    </div>
                  </CardHeader>
                  <CardContent>
                    <p className="text-sm text-foreground leading-relaxed whitespace-pre-wrap">
                      {item.data.content}
                    </p>
                  </CardContent>
                </Card>
              ) : (
                <Card
                  key={item.data.id}
                  className="border shadow-sm hover:shadow-md transition-all overflow-hidden"
                  style={{
                    borderColor: theme.ui.cardBorder,
                    backgroundColor: theme.ui.glassBg,
                    backdropFilter: 'blur(10px) saturate(180%)',
                    WebkitBackdropFilter: 'blur(10px) saturate(180%)',
                    boxShadow: theme.ui.glassShadow,
                  }}
                >
                  <CardHeader className="pb-2">
                    <div className="flex items-start justify-between gap-2 mb-2">
                      <CardTitle className="section-title text-sm leading-snug" style={{ color: theme.primaryDark }}>
                        {item.data.title}
                      </CardTitle>
                    </div>
                    <div className="flex items-center gap-1.5 flex-wrap">
                      <Badge className={`text-[11px] ${platformColors[item.data.platform]} border-0`}>
                        {item.data.platform}
                      </Badge>
                      <Badge className={`text-[11px] ${categoryColors[item.data.category]} border-0`}>
                        {item.data.category}
                      </Badge>
                    </div>
                  </CardHeader>
                  <CardContent className="pt-0">
                    <div className="md:hidden">
                      <div className={`collapse-grid ${expandedTipId === item.data.id ? 'collapse-expanded' : 'collapse-collapsed'}`}>
                        <div className="collapse-inner">
                          <RichTipText
                            text={item.data.description}
                            accentColor={theme.primaryDark}
                          />
                        </div>
                      </div>
                      <button
                        onClick={(e) => { e.stopPropagation(); toggleTip(item.data.id); }}
                        className="flex items-center gap-1 mt-2 text-xs font-medium"
                        style={{ color: theme.primary }}
                      >
                        {expandedTipId === item.data.id ? '收起' : '展开全文'}
                        <ChevronDown className={`size-3 transition-transform duration-300 ${expandedTipId === item.data.id ? 'rotate-180' : ''}`} />
                      </button>
                    </div>
                    <div className="hidden md:block">
                      <RichTipText
                        text={item.data.description}
                        accentColor={theme.primaryDark}
                      />
                    </div>
                  </CardContent>
                </Card>
              )
            ))
          )}
        </div>

      </div>
      </CollapsibleSection>
      {/* 我的运营笔记 */}
      {!isSearchMode && (
        <CollapsibleSection
          title="我的运营笔记"
          subtitle="随时记录心得与踩坑经验"
          summary={`${operationNotes.length} 条笔记`}
          badge={`${operationNotes.length} 条`}
          badgeColor="default"
          theme={theme}
          expanded={expandedId === 'notes'}
          onToggle={() => toggleSection('notes')}
          icon={<NotebookPen className="size-5" />}
          className="!shadow-none !border-0"
        >
          <NotePadSection
            storageKey="note:operation"
            title="我的运营笔记"
            icon={<NotebookPen className="size-4" />}
            theme={theme}
            placeholder="记录运营心得、踩坑经验、独门技巧..."
            onNotesChange={setOperationNotes}
          />
        </CollapsibleSection>
      )}

       {/* 数据异常排查模块（放在每日推荐内容下方） */}
       {!isSearchMode && (
         <CollapsibleSection
           title="后台数据异常排查"
           subtitle="数据现象 = 核心判断｜排查重点｜立即执行"
           summary="8大维度快速定位运营数据问题"
           badge="8 维"
           badgeColor="danger"
           theme={theme}
           expanded={expandedId === 'diagnosis'}
           onToggle={() => toggleSection('diagnosis')}
           icon={<AlertTriangle className="size-5" />}
           className="!shadow-none !border-0"
         >
         <div className="space-y-3">
           <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            {DATA_DIAGNOSIS_LIST.map((item, i) => (
              <DiagnosisCard key={i} item={item} theme={theme} />
            ))}
           </div>
          </div>
          </CollapsibleSection>
        )}

     </div>
  );
}
